create table public.social_posts(id uuid primary key default gen_random_uuid(),author_id uuid not null references auth.users(id) on delete cascade,body text not null check(nullif(btrim(body),'') is not null),visibility text not null default 'public' check(visibility in('public','connections','private')),context text not null default 'social' check(context in('social','professional','romantic','community')),location_label text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz); create table public.social_reactions(post_id uuid not null references public.social_posts(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,reaction text not null default 'like',created_at timestamptz not null default now(),primary key(post_id,user_id)); create table public.social_comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.social_posts(id) on delete cascade,author_id uuid not null references auth.users(id) on delete cascade,body text not null check(nullif(btrim(body),'') is not null),created_at timestamptz not null default now(),deleted_at timestamptz); create table public.social_location_shares(user_id uuid primary key references auth.users(id) on delete cascade,enabled boolean not null default false,audience text not null default 'selected' check(audience in('connections','selected','nobody')),latitude double precision,longitude double precision,accuracy_meters double precision,expires_at timestamptz,updated_at timestamptz not null default now(),check(enabled=false or(latitude is not null and longitude is not null))); alter table public.social_posts enable row level security; alter table public.social_reactions enable row level security; alter table public.social_comments enable row level security; alter table public.social_location_shares enable row level security; create or replace function public.pantavion_are_connections(a uuid,b uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$select exists(select 1 from public.relationships where status='accepted' and ((requester_id=a and addressee_id=b) or(requester_id=b and addressee_id=a)))$$; revoke all on function public.pantavion_are_connections(uuid,uuid) from public; grant execute on function public.pantavion_are_connections(uuid,uuid) to authenticated; create policy social_posts_read on public.social_posts for select to authenticated using(deleted_at is null and(author_id=auth.uid() or visibility='public' or(visibility='connections' and public.pantavion_are_connections(author_id,auth.uid())))); create policy social_posts_write on public.social_posts for all to authenticated using(author_id=auth.uid()) with check(author_id=auth.uid()); create policy social_reactions_read on public.social_reactions for select to authenticated using(exists(select 1 from public.social_posts p where p.id=post_id and p.deleted_at is null)); create policy social_reactions_write on public.social_reactions for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy social_comments_read on public.social_comments for select to authenticated using(deleted_at is null and exists(select 1 from public.social_posts p where p.id=post_id and p.deleted_at is null)); create policy social_comments_write on public.social_comments for all to authenticated using(author_id=auth.uid()) with check(author_id=auth.uid()); create policy social_location_self on public.social_location_shares for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); grant select,insert,update,delete on public.social_posts,public.social_reactions,public.social_comments,public.social_location_shares to authenticated;